cat << 'EOF' > test-ajv.js
const Ajv = require('ajv');
const ajv = new Ajv({ strict: false, validateFormats: false });
const validate = ajv.compile({ type: 'object', properties: { ssn: { type: 'string' } } });
validate({ ssn: 123456789 });
console.log(validate.errors);
EOF
node test-ajv.js

cat << 'EOF' > test-test.ts
import { ToolRegistry } from './src/orchestration/tools/registry.js';
async function run() {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'ssn_lookup',
      description: 'Look up record by identifier',
      inputSchema: {
        type: 'object',
        properties: {ssn: {type: 'string'}},
        required: ['ssn'],
      },
    },
    async () => 'found'
  );
  const response = await registry.execute('ssn_lookup', {ssn: 123456789});
  console.log(response);
}
run();
EOF
npx tsx test-test.ts

